import{_ as o,c as a,o as c,ae as t}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"商城示例","description":"","frontmatter":{},"headers":[],"relativePath":"guide/commerce.md","filePath":"guide/commerce.md","lastUpdated":1792605191000}'),d={name:"guide/commerce.md"};function i(n,e,r,s,p,l){return c(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="商城示例" tabindex="-1">商城示例 <a class="header-anchor" href="#商城示例" aria-label="Permalink to &quot;商城示例&quot;">​</a></h1><p>商城不是按钮 Demo，而是一条真实 Server State 链路。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h2><ul><li><code>/shop</code>：公开商品列表、关键词搜索、分类、排序和 Infinite Query。</li><li><code>/shop/products/:id</code>：商品详情、数量、Safe Area 底部购买栏。</li><li><code>/shop/admin/products</code>：登录且为 admin 后的商品查询、创建、编辑、上下架和软删除。</li></ul><p>商品卡片与编辑器位于 <code>src/components/shop</code>，页面只负责路由级组合。业务接口集中在 <code>src/api/modules/products.ts</code>，缓存、取消、Mutation 与失效由 TanStack Query 管理，不进入 Pinia。</p><h2 id="类型与数据" tabindex="-1">类型与数据 <a class="header-anchor" href="#类型与数据" aria-label="Permalink to &quot;类型与数据&quot;">​</a></h2><p>商品类型由 <code>openapi/schema.yaml</code> 生成。金额以整数分存储，避免浮点误差；展示时由 <code>Intl.NumberFormat</code> 格式化。名称、卖点和详情必须包含 <code>zh-CN</code>、<code>en-US</code> 与 <code>ja-JP</code>，切换语言后读取对应字段。</p><p>封面只允许同源路径或 HTTPS URL，异常值回退到本地占位图。后台删除使用软删除，公开 API 只展示 <code>on_sale</code> 商品。</p><h2 id="mock-与真实后端" tabindex="-1">Mock 与真实后端 <a class="header-anchor" href="#mock-与真实后端" aria-label="Permalink to &quot;Mock 与真实后端&quot;">​</a></h2><p><code>pnpm dev</code> 使用 <code>mock/index.ts</code>，无需 Docker 即可浏览和编辑商品。<code>pnpm dev:integration</code> 配置 Gin／FastAPI 代理。启用代理不代表所有旧业务契约已匹配，见下方接入边界。</p><h2 id="收藏交互与会话隔离" tabindex="-1">收藏交互与会话隔离 <a class="header-anchor" href="#收藏交互与会话隔离" aria-label="Permalink to &quot;收藏交互与会话隔离&quot;">​</a></h2><p><code>FavoriteButton</code> 接收数值 <code>productId</code> 和当前 <code>session</code> Token。未登录时显示登录链接，不请求私有状态；登录后先读取已保存的状态，再启用操作。读取失败可重试，写入失败保留最后确认的状态并提示错误。读取和保存期间禁用重复提交。</p><p>收藏状态由 TanStack Query 管理。缓存键包含控件实例、会话代数和商品 ID，不包含 Token。Mutation 捕获提交时的缓存键，旧响应只更新原来的缓存，不能覆盖另一个账号或商品。重新挂载、切换会话后重新读取服务端。操作提交明确的布尔值，不让服务端反转一个未知状态。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /api/product/favorite?id=1</span></span>
<span class="line"><span>POST /api/product/favorite</span></span>
<span class="line"><span>{ &quot;productId&quot;: 1, &quot;favorite&quot;: true }</span></span></code></pre></div><p><code>src/components/shop/FavoriteButton.vue</code> → <code>src/api/modules/favorites.ts</code> → <code>apiClient</code>.</p><p>响应包装兼容不会自动转换路径或业务字段。单应用商品模块仍使用 <code>/api/products</code> 与多语言 <code>name</code>／<code>priceCents</code>，当前 Gin 商品接口为 <code>/api/product/list</code> 与 <code>title</code>／<code>price</code>；登录也存在 <code>name</code>／<code>token</code> 与 <code>username</code>／<code>accessToken</code> 的差异。完整联调前需要核对其余契约或增加明确的领域适配。新增收藏路径已与 Gin 对齐，但鉴权仍需要兼容的已签发 JWT。</p><h2 id="详情链接与页面复用" tabindex="-1">详情链接与页面复用 <a class="header-anchor" href="#详情链接与页面复用" aria-label="Permalink to &quot;详情链接与页面复用&quot;">​</a></h2><p>详情页仅接受正整数十进制 ID，数值必须在 JavaScript 安全整数范围内。缺失、重复、负数、小数、指数写法或超范围 ID 不会触发详情请求，而是显示无效链接提示和返回商品列表的入口。</p><p>同一详情组件切换商品时，数量重置为 1，并清除上一件商品的操作提示。库存刷新时数量收敛到可用范围；缺货或未上架时禁用详情页购买和数量操作。远程详情继续由 TanStack Query 管理并传递 <code>AbortSignal</code>，不复制进购物车状态。</p><p><a href="./request">API</a> · <a href="./testing">测试</a></p>`,20)])])}const m=o(d,[["render",i]]);export{h as __pageData,m as default};
